export type LayerType = 'image' | 'video' | 'text';

export interface LayerAdjustments {
  brightness: number;   // 0 to 2 (1 is default)
  contrast: number;     // 0 to 2 (1 is default)
  saturation: number;   // 0 to 2 (1 is default)
  hueRotate: number;    // 0 to 360
  blur: number;         // 0 to 20
}

export interface TextConfig {
  content: string;
  fontSize: number;
  fontFamily: string;
  color: string;
  fontWeight: string;
  fontStyle?: 'normal' | 'italic';
  textAlign?: 'left' | 'center' | 'right';
  letterSpacing?: number;
  lineHeight?: number;
  strokeWidth?: number;
  strokeColor?: string;
  shadowBlur?: number;
  shadowColor?: string;
  shadowOffsetX?: number;
  shadowOffsetY?: number;
  textTransform?: 'none' | 'uppercase' | 'lowercase';
}

export interface Layer {
  id: string;
  type: LayerType;
  dataUrl: string;
  name: string;
  x: number; // Center X
  y: number; // Center Y
  scale: number;
  rotation: number; // Degrees
  opacity: number;
  visible: boolean;
  zIndex: number;
  width: number;  // Current width (at scale 1)
  height: number; // Current height (at scale 1)
  flipX?: boolean;
  flipY?: boolean;
  adjustments?: LayerAdjustments;

  // Text specific
  textConfig?: TextConfig;

  // Depth specific
  depthEnabled?: boolean;
  depthOffset?: number; // -128 to 128
  flattenDepth?: boolean;
  computedFgDepthUrl?: string;
  computedBgDepthUrl?: string;
  computedBgCompositeUrl?: string;
  depthMaskUrl?: string;
}

export interface Point {
  x: number;
  y: number;
}

declare global {
  interface Window {
    aistudio?: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

export const DEFAULT_CANVAS_WIDTH = 1344;
export const DEFAULT_CANVAS_HEIGHT = 768;

export const CANVAS_PRESETS = [
  { name: '1:1 Square', width: 1080, height: 1080 },
  { name: '16:9 Cinematic', width: 1920, height: 1080 },
  { name: '9:16 Portrait', width: 1080, height: 1920 },
  { name: '4:3 Standard', width: 1440, height: 1080 },
  { name: '3:2 Photo', width: 1500, height: 1000 },
  { name: 'Default', width: 1344, height: 768 },
];

import { useState, useCallback, useRef } from 'react';
import { Layer } from '../types';

interface HistoryState {
  layers: Layer[];
  canvasWidth: number;
  canvasHeight: number;
}

export const useHistory = (initialState: HistoryState) => {
  const [canUndo, setCanUndo] = useState(false);
  const [canRedo, setCanRedo] = useState(false);

  const pastRef = useRef<HistoryState[]>([]);
  const futureRef = useRef<HistoryState[]>([]);

  const push = useCallback((state: HistoryState) => {
    // Deep clone to ensure history is immutable
    const snapshot = JSON.parse(JSON.stringify(state));
    pastRef.current.push(snapshot);
    if (pastRef.current.length > 50) {
      pastRef.current.shift();
    }
    futureRef.current = [];
    setCanUndo(true);
    setCanRedo(false);
  }, []);

  const undo = useCallback((currentState: HistoryState) => {
    if (pastRef.current.length === 0) return null;

    const previous = pastRef.current.pop()!;
    futureRef.current.push(JSON.parse(JSON.stringify(currentState)));

    setCanUndo(pastRef.current.length > 0);
    setCanRedo(true);

    return previous;
  }, []);

  const redo = useCallback((currentState: HistoryState) => {
    if (futureRef.current.length === 0) return null;

    const next = futureRef.current.pop()!;
    pastRef.current.push(JSON.parse(JSON.stringify(currentState)));

    setCanUndo(true);
    setCanRedo(futureRef.current.length > 0);

    return next;
  }, []);

  const clear = useCallback(() => {
    pastRef.current = [];
    futureRef.current = [];
    setCanUndo(false);
    setCanRedo(false);
  }, []);

  return { push, undo, redo, clear, canUndo, canRedo };
};

import React, { useState, useRef, useEffect } from 'react';
import { ImageIcon, Camera, Plus } from 'lucide-react';
import { PillButton } from './UIPrimitives';

interface AddImageDropdownProps {
  onGallery: () => void;
  onCamera: () => void;
  disabled?: boolean;
  className?: string;
}

export const AddImageDropdown: React.FC<AddImageDropdownProps> = ({
  onGallery,
  onCamera,
  disabled,
  className = "w-full"
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAction = (action: () => void) => {
    if (disabled) return;
    action();
    setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      <div className="w-full">
        <PillButton
          onClick={() => !disabled && setIsOpen(!isOpen)}
          disabled={disabled}
          variant={isOpen ? 'filled' : 'outline'}
          icon={<Plus size={18} className="transition-transform duration-300" />}
        >
          Add Image
        </PillButton>
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-full bg-[#1a1a1a] border border-[#595959] rounded-xl overflow-hidden shadow-2xl backdrop-blur-md animate-dropdown origin-top z-[100]">
          <div className="p-1 space-y-0.5">
            <button
              onClick={() => handleAction(onGallery)}
              className="w-full flex items-center gap-2.5 px-2.5 py-2 text-[11px] font-medium text-[rgba(218,220,224,0.9)] hover:text-white hover:bg-[#333] rounded-lg transition-colors group"
            >
              <ImageIcon size={14} className="text-[rgba(218,220,224,0.55)] group-hover:text-white" />
              <span>Gallery</span>
            </button>

            <button
              onClick={() => handleAction(onCamera)}
              className="w-full flex items-center gap-2.5 px-2.5 py-2 text-[11px] font-medium text-[rgba(218,220,224,0.9)] hover:text-white hover:bg-[#333] rounded-lg transition-colors group"
            >
              <Camera size={14} className="text-[rgba(218,220,224,0.55)] group-hover:text-white" />
              <span>Webcam</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useRef, useEffect } from 'react';
import { Point } from '../types';

interface CropOverlayProps {
  cropRect: { x: number; y: number; width: number; height: number };
  onUpdateCrop: (rect: { x: number; y: number; width: number; height: number }) => void;
  canvasWidth: number; // LayerWidth
  canvasHeight: number; // LayerHeight
  zoom: number;
}

type CropHandleMode = 'none' | 'move' | 'nw' | 'ne' | 'sw' | 'se' | 'n' | 's' | 'e' | 'w';

export const CropOverlay: React.FC<CropOverlayProps> = ({
  cropRect,
  onUpdateCrop,
  canvasWidth,
  canvasHeight,
  zoom
}) => {
  const interactionRef = useRef<{
    mode: CropHandleMode;
    startMouse: Point;
    startRect: { x: number; y: number; width: number; height: number };
  }>({ mode: 'none', startMouse: { x: 0, y: 0 }, startRect: cropRect });

  const handlePointerDown = (e: React.PointerEvent, mode: CropHandleMode) => {
    e.stopPropagation();
    const target = e.currentTarget as HTMLElement;
    target.setPointerCapture(e.pointerId);

    interactionRef.current = {
      mode,
      startMouse: { x: e.clientX, y: e.clientY },
      startRect: { ...cropRect }
    };
  };

  useEffect(() => {
    const handlePointerMove = (e: PointerEvent) => {
      const { mode, startMouse, startRect } = interactionRef.current;
      if (mode === 'none') return;

      const dx = (e.clientX - startMouse.x);
      const dy = (e.clientY - startMouse.y);

      const dxPct = dx / (zoom * canvasWidth);
      const dyPct = dy / (zoom * canvasHeight);

      let nextRect = { ...startRect };

      if (mode === 'move') {
        nextRect.x = Math.min(Math.max(0, startRect.x + dxPct), 1 - nextRect.width);
        nextRect.y = Math.min(Math.max(0, startRect.y + dyPct), 1 - nextRect.height);
      } else {
        if (mode.includes('n')) {
          const newY = Math.min(Math.max(0, startRect.y + dyPct), startRect.y + startRect.height - 0.05);
          nextRect.height = startRect.height + (startRect.y - newY);
          nextRect.y = newY;
        }
        if (mode.includes('s')) {
          nextRect.height = Math.min(Math.max(0.05, startRect.height + dyPct), 1 - startRect.y);
        }
        if (mode.includes('w')) {
          const newX = Math.min(Math.max(0, startRect.x + dxPct), startRect.x + startRect.width - 0.05);
          nextRect.width = startRect.width + (startRect.x - newX);
          nextRect.x = newX;
        }
        if (mode.includes('e')) {
          nextRect.width = Math.min(Math.max(0.05, startRect.width + dxPct), 1 - startRect.x);
        }
      }

      onUpdateCrop(nextRect);
    };

    const handlePointerUp = () => {
      interactionRef.current.mode = 'none';
    };

    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [canvasWidth, canvasHeight, zoom, onUpdateCrop]);

  const bracketClass = "absolute w-8 h-8 border-white drop-shadow-[0_4px_8px_rgba(0,0,0,0.8)] z-50 pointer-events-none";
  const edgeClass = "absolute bg-white drop-shadow-[0_4px_8px_rgba(0,0,0,0.8)] z-50 pointer-events-none";

  return (
    <div className="absolute inset-0 pointer-events-none z-[400] w-full h-full overflow-visible">
      <div 
        className="absolute bg-transparent shadow-[0_0_0_9999px_rgba(0,0,0,0.65)] ring-2 ring-white/60 pointer-events-auto cursor-move overflow-visible"
        style={{
          left: `${cropRect.x * 100}%`,
          top: `${cropRect.y * 100}%`,
          width: `${cropRect.width * 100}%`,
          height: `${cropRect.height * 100}%`,
        }}
        onPointerDown={(e) => handlePointerDown(e, 'move')}
      >
        {/* Rule of Thirds Grid */}
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute top-1/3 left-0 w-full h-px bg-white/40" />
          <div className="absolute top-2/3 left-0 w-full h-px bg-white/40" />
          <div className="absolute left-1/3 top-0 w-px h-full bg-white/40" />
          <div className="absolute left-2/3 top-0 w-px h-full bg-white/40" />
        </div>

        {/* Photoshop-style Corner Brackets (Sit outside the ring) */}
        <div className={`${bracketClass} -top-3 -left-3 border-t-[6px] border-l-[6px]`} />
        <div className={`${bracketClass} -top-3 -right-3 border-t-[6px] border-r-[6px]`} />
        <div className={`${bracketClass} -bottom-3 -left-3 border-b-[6px] border-l-[6px]`} />
        <div className={`${bracketClass} -bottom-3 -right-3 border-b-[6px] border-r-[6px]`} />

        {/* Interaction Areas for Corners (Larger for touch/mouse ease) */}
        <div className="absolute -top-10 -left-10 w-20 h-20 cursor-nw-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'nw')} />
        <div className="absolute -top-10 -right-10 w-20 h-20 cursor-ne-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'ne')} />
        <div className="absolute -bottom-10 -left-10 w-20 h-20 cursor-sw-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'sw')} />
        <div className="absolute -bottom-10 -right-10 w-20 h-20 cursor-se-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'se')} />

        {/* Photoshop-style Edge Bars */}
        <div className={`${edgeClass} top-1/2 -left-3 -translate-y-1/2 w-[6px] h-10`} />
        <div className={`${edgeClass} top-1/2 -right-3 -translate-y-1/2 w-[6px] h-10`} />
        <div className={`${edgeClass} -top-3 left-1/2 -translate-x-1/2 w-10 h-[6px]`} />
        <div className={`${edgeClass} -bottom-3 left-1/2 -translate-x-1/2 w-10 h-[6px]`} />

        {/* Interaction Areas for Edges */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-24 h-12 -translate-y-6 cursor-n-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'n')} />
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-24 h-12 translate-y-6 cursor-s-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 's')} />
        <div className="absolute left-0 top-1/2 -translate-y-1/2 w-12 h-24 -translate-x-6 cursor-w-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'w')} />
        <div className="absolute right-0 top-1/2 -translate-y-1/2 w-12 h-24 translate-x-6 cursor-e-resize z-[60]" onPointerDown={(e) => handlePointerDown(e, 'e')} />
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { Layer, Point } from '../types';
import { TransformOverlay } from './TransformOverlay';
import { CropOverlay } from './CropOverlay';
import { InpaintOverlay } from './InpaintOverlay';

interface EditorCanvasProps {
  layers: Layer[];
  activeLayerId: string | null;
  onSelectLayer: (id: string | null) => void;
  onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
  canvasWidth: number;
  canvasHeight: number;
  isCropping: boolean;
  isInpainting: boolean;
  isOutpainting: boolean;
  isProcessing?: boolean;
  cropRect: { x: number; y: number; width: number; height: number };
  onUpdateCrop: (rect: { x: number; y: number; width: number; height: number }) => void;
  onCommitHistory: () => void;
  onInpaintRequest: () => void;
  onUpdateMask: (maskUrl: string) => void;
}

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  layers, activeLayerId, onSelectLayer, onUpdateLayer, canvasWidth, canvasHeight,
  isCropping, isInpainting, isOutpainting, isProcessing, cropRect, onUpdateCrop, onCommitHistory, onInpaintRequest, onUpdateMask
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(0.5);
  const [offset, setOffset] = useState<Point>({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const panStartRef = useRef<Point>({ x: 0, y: 0 });
  const hasInitialFit = useRef(false);

  // Smart Fit Logic: Calculate optimal zoom on mount
  useEffect(() => {
    if (!containerRef.current || hasInitialFit.current) return;

    const fitToScreen = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();

      // Use minimal margins to maximize canvas visibility between sidebars
      const horizontalMargin = 40;
      const verticalMargin = 160; // Enough space for toolbar/prompt bar

      const availW = Math.max(rect.width - horizontalMargin, 100);
      const availH = Math.max(rect.height - verticalMargin, 100);

      const zoomW = availW / canvasWidth;
      const zoomH = availH / canvasHeight;

      const fitZoom = Math.min(zoomW, zoomH) * 0.98; // Tighter fit to screen edges
      setZoom(Math.min(Math.max(fitZoom, 0.1), 3));
      hasInitialFit.current = true;
    };

    fitToScreen();
    window.addEventListener('resize', fitToScreen);
    return () => window.removeEventListener('resize', fitToScreen);
  }, [canvasWidth, canvasHeight]);

  const activeLayer = useMemo(() => layers.find((l) => l.id === activeLayerId), [layers, activeLayerId]);

  const getWorldMouse = useCallback((clientX: number, clientY: number) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    const relX = clientX - (rect.left + rect.width / 2);
    const relY = clientY - (rect.top + rect.height / 2);
    return {
      x: (relX - offset.x) / zoom + canvasWidth / 2,
      y: (relY - offset.y) / zoom + canvasHeight / 2
    };
  }, [offset, zoom, canvasWidth, canvasHeight]);

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isInpainting) return;
    if (e.target === containerRef.current || (e.target as HTMLElement).id === 'canvas-bg') {
      onSelectLayer(null);
      setIsPanning(true);
      panStartRef.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
      (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isPanning) {
      setOffset({ x: e.clientX - panStartRef.current.x, y: e.clientY - panStartRef.current.y });
    }
  };

  useEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        setZoom(prev => Math.min(Math.max(0.05, prev + (-e.deltaY * 0.001 * prev * 2)), 10));
      } else {
        if (isInpainting) return; 
        e.preventDefault();
        setOffset(prev => ({ x: prev.x - e.deltaX, y: prev.y - e.deltaY }));
      }
    };
    const container = containerRef.current;
    container?.addEventListener('wheel', handleWheel, { passive: false });
    return () => container?.removeEventListener('wheel', handleWheel);
  }, [isInpainting]);

  const sortedLayers = useMemo(() => [...layers].sort((a, b) => a.zIndex - b.zIndex), [layers]);

  return (
    <div
      ref={containerRef}
      className={`relative w-full h-full overflow-hidden bg-zinc-950 flex items-center justify-center ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={() => setIsPanning(false)}
    >
      <div 
        className="relative pointer-events-none shrink-0"
        style={{ 
          transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom})`, 
          width: canvasWidth, 
          height: canvasHeight 
        }}
      >
        <div 
          id="canvas-bg"
          className="absolute inset-0 bg-zinc-900 shadow-2xl outline outline-1 outline-white/10 overflow-hidden pointer-events-auto" 
          onPointerDown={(e) => { 
            if ((e.target as HTMLElement).id === 'canvas-bg') handlePointerDown(e); 
          }}
        >
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10 pointer-events-none" />

          {/* Magic Shimmer Effect Layer for Outpainting */}
          {isOutpainting && isProcessing && (
            <div className="absolute inset-0 z-0 pointer-events-none animate-in fade-in duration-1000">
              <div className="absolute inset-0 bg-white/[0.03] mix-blend-overlay" />
              <div className="absolute inset-0 shadow-[inset_0_0_150px_rgba(255,255,255,0.15)] animate-pulse" />
              <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(255,255,255,0.05)_0%,transparent_100%)] animate-pulse" />
              <div className="absolute inset-0 overflow-hidden opacity-20">
                <div className="absolute top-0 left-0 w-full h-full bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.3)_50%,transparent_75%)] animate-shimmer" />
              </div>
            </div>
          )}

          {sortedLayers.map((layer) => {
            const filterStyle = layer.adjustments ? `brightness(${layer.adjustments.brightness}) contrast(${layer.adjustments.contrast}) saturate(${layer.adjustments.saturation}) hue-rotate(${layer.adjustments.hueRotate}deg) blur(${layer.adjustments.blur}px)` : 'none';

            return (
              <div
                key={layer.id}
                onPointerDown={(e) => {
                  if (isCropping || isOutpainting || isInpainting) return;
                  e.stopPropagation();
                  onSelectLayer(layer.id);
                }}
                onDoubleClick={(e) => {
                  if (isCropping || isOutpainting || isInpainting) return;
                  e.stopPropagation();
                  onSelectLayer(layer.id);
                  if (layer.type === 'text') {
                    // Slight delay to ensure the properties sidebar has time to render if it wasn't active
                    setTimeout(() => {
                      const input = document.getElementById('text-property-input') as HTMLTextAreaElement;
                      if (input) {
                        input.focus();
                        input.select();
                      }
                    }, 50);
                  }
                }}
                className={`absolute select-none group ${!layer.visible ? 'pointer-events-none opacity-0' : ''}`}
                style={{ 
                  left: layer.x, 
                  top: layer.y, 
                  width: layer.width * layer.scale, 
                  height: layer.height * layer.scale, 
                  transform: `translate(-50%, -50%) rotate(${layer.rotation}deg)`, 
                  opacity: layer.visible ? layer.opacity : 0, 
                  zIndex: layer.zIndex + 10,
                  WebkitMaskImage: layer.depthMaskUrl ? `url(${layer.depthMaskUrl})` : 'none',
                  maskImage: layer.depthMaskUrl ? `url(${layer.depthMaskUrl})` : 'none',
                  WebkitMaskSize: '100% 100%',
                  maskSize: '100% 100%',
                }}
              >
                <div className="relative w-full h-full" style={{ transform: `scale(${layer.flipX ? -1 : 1}, ${layer.flipY ? -1 : 1})`, filter: filterStyle }}>
                  <img src={layer.dataUrl} className="w-full h-full object-fill" draggable={false} />

                  {isInpainting && activeLayerId === layer.id && (
                    <InpaintOverlay 
                      width={layer.width} 
                      height={layer.height} 
                      isProcessing={isProcessing}
                      onUpdate={onUpdateMask} 
                      onRightClick={(e) => {
                        e.stopPropagation();
                        onInpaintRequest();
                      }}
                    />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="absolute inset-0 pointer-events-none overflow-visible z-[5000]">
          {activeLayer && !isOutpainting && !isInpainting && (
            isCropping ? (
              <div 
                className="absolute pointer-events-none overflow-visible"
                style={{
                  left: activeLayer.x,
                  top: activeLayer.y,
                  width: activeLayer.width * activeLayer.scale,
                  height: activeLayer.height * activeLayer.scale,
                  transform: `translate(-50%, -50%) rotate(${activeLayer.rotation}deg)`,
                }}
              >
                <CropOverlay 
                  cropRect={cropRect} 
                  onUpdateCrop={onUpdateCrop} 
                  canvasWidth={activeLayer.width * activeLayer.scale} 
                  canvasHeight={activeLayer.height * activeLayer.scale}
                  zoom={zoom}
                />
              </div>
            ) : (
              <TransformOverlay 
                activeLayer={activeLayer} 
                zoom={zoom} 
                offset={offset} 
                canvasWidth={canvasWidth}
                canvasHeight={canvasHeight}
                onUpdateLayer={onUpdateLayer} 
                getWorldMouse={getWorldMouse} 
                onCommitHistory={onCommitHistory}
              />
            )
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { Point } from '../types';

interface InpaintOverlayProps {
  width: number;
  height: number;
  onUpdate: (dataUrl: string) => void;
  onRightClick: (e: React.MouseEvent) => void;
  isProcessing?: boolean;
}

export const InpaintOverlay: React.FC<InpaintOverlayProps> = ({ 
  width, 
  height, 
  onUpdate, 
  onRightClick,
  isProcessing 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasMask, setHasMask] = useState(false);

  const pathsRef = useRef<Point[][]>([]);
  const currentPathRef = useRef<Point[]>([]);

  const redrawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const allPaths = [...pathsRef.current];
    if (currentPathRef.current.length > 0) {
      allPaths.push(currentPathRef.current);
    }
    if (allPaths.length === 0) return;

    // 1. Draw thick black dashed outline
    ctx.globalCompositeOperation = 'source-over';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.shadowBlur = 0;

    ctx.lineWidth = 48; // Slightly thicker to form a border
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.setLineDash([8, 12]);

    ctx.beginPath();
    for (const path of allPaths) {
      if (path.length === 0) continue;
      ctx.moveTo(path[0].x, path[0].y);
      for (let i = 1; i < path.length; i++) {
        ctx.lineTo(path[i].x, path[i].y);
      }
    }
    ctx.stroke();

    // 2. Cut out the middle to make it an outline
    ctx.globalCompositeOperation = 'destination-out';
    ctx.setLineDash([]);
    ctx.lineWidth = 44; 
    ctx.strokeStyle = 'black'; 
    ctx.beginPath();
    for (const path of allPaths) {
      if (path.length === 0) continue;
      ctx.moveTo(path[0].x, path[0].y);
      for (let i = 1; i < path.length; i++) {
        ctx.lineTo(path[i].x, path[i].y);
      }
    }
    ctx.stroke();

    // 3. Fill the middle with semi-transparent white
    ctx.globalCompositeOperation = 'source-over';
    ctx.lineWidth = 44;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.shadowBlur = 15;
    ctx.shadowColor = 'rgba(255, 255, 255, 0.2)';
    ctx.beginPath();
    for (const path of allPaths) {
      if (path.length === 0) continue;
      ctx.moveTo(path[0].x, path[0].y);
      for (let i = 1; i < path.length; i++) {
        ctx.lineTo(path[i].x, path[i].y);
      }
    }
    ctx.stroke();
  };

  const getPos = (e: React.PointerEvent): Point => {
    const rect = canvasRef.current!.getBoundingClientRect();
    const scaleX = width / rect.width;
    const scaleY = height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isProcessing || e.button !== 0) return;
    setIsDrawing(true);
    setHasMask(true);
    const pos = getPos(e);
    currentPathRef.current = [pos];
    redrawCanvas();
    canvasRef.current?.setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDrawing || isProcessing) return;
    const pos = getPos(e);
    currentPathRef.current.push(pos);
    redrawCanvas();
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
    if (currentPathRef.current.length > 0) {
      pathsRef.current.push([...currentPathRef.current]);
      currentPathRef.current = [];
    }
    if (canvasRef.current) {
      onUpdate(canvasRef.current.toDataURL('image/png'));
    }
  };

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!isProcessing && hasMask) onRightClick(e);
  };

  const maskDataUrl = canvasRef.current?.toDataURL();

  return (
    <div className={`absolute inset-0 z-[1000] ${isProcessing ? 'pointer-events-none' : 'cursor-crosshair'} group`}>
      {/* The drawing canvas itself is hidden during processing to show only the "magic" effect */}
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        className={`w-full h-full touch-none transition-opacity duration-500 ${isProcessing ? 'opacity-0' : 'opacity-100'}`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onContextMenu={handleContextMenu}
      />

      {/* Magic "Magic" Scanning Effect Layer */}
      {isProcessing && maskDataUrl && (
        <div 
          className="absolute inset-0 pointer-events-none overflow-hidden animate-in fade-in duration-700"
          style={{ 
            maskImage: `url(${maskDataUrl})`,
            WebkitMaskImage: `url(${maskDataUrl})`,
            maskSize: '100% 100%',
            WebkitMaskSize: '100% 100%'
          }}
        >
          {/* Shimmer Base */}
          <div className="absolute inset-0 bg-white/10 mix-blend-overlay" />

          {/* Scanning Wave */}
          <div className="absolute inset-0 bg-gradient-to-b from-transparent via-white/40 to-transparent h-[200%] animate-scan-wave" />

          {/* Shimmer Magic */}
          <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.4)_50%,transparent_75%)] animate-shimmer opacity-40" />

          {/* Inner Glow */}
          <div className="absolute inset-0 shadow-[inset_0_0_100px_rgba(255,255,255,0.3)] animate-pulse" />
        </div>
      )}

      {!isProcessing && !isDrawing && (
        <div className="absolute top-4 left-1/2 -translate-x-1/2 pointer-events-none bg-zinc-900/80 backdrop-blur-md border border-white/10 px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest text-zinc-400 group-hover:opacity-0 transition-opacity shadow-2xl">
          {hasMask ? 'Right click to prompt' : 'Paint area to edit'}
        </div>
      )}
    </div>
  );
};

