import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Wand2, X, CornerDownLeft } from 'lucide-react';

interface PromptBarProps {
  isActive: boolean;
  mode: 'refine' | 'inpaint' | 'outpaint';
  onClose: () => void;
  onConfirm: (prompt: string) => void;
  isProcessing: boolean;
  defaultPrompt?: string;
}

export const PromptBar: React.FC<PromptBarProps> = ({
  isActive,
  mode,
  onClose,
  onConfirm,
  isProcessing,
  defaultPrompt = ""
}) => {
  const [prompt, setPrompt] = useState(defaultPrompt);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (isActive) {
      setPrompt(defaultPrompt);
      // Wait for layout and animation to begin then force focus
      requestAnimationFrame(() => {
        setTimeout(() => inputRef.current?.focus(), 50);
      });
    }
  }, [isActive, defaultPrompt]);

  const isRefine = mode === 'refine';
  const isOutpaint = mode === 'outpaint';

  let placeholder = "What should appear in the painted area?";
  if (isRefine) placeholder = "Describe how to refine this image...";
  if (isOutpaint) placeholder = "Describe what to generate around the image (optional)...";

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isActive || isProcessing) return;
      if (e.key === 'Enter' && !e.shiftKey && (mode !== 'inpaint' || prompt.trim().length > 0)) {
        e.preventDefault();
        onConfirm(prompt);
      }
      if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isActive, isProcessing, prompt, onConfirm, onClose, mode]);

  if (!isActive) return null;

  const isAvailable = !isProcessing && (mode !== 'inpaint' || prompt.trim().length > 0);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey && isAvailable) {
      e.preventDefault();
      onConfirm(prompt);
    }
  };

  return (
    <div className="w-full animate-in slide-in-from-bottom-4 fade-in duration-300">
      <div className="relative group">
        <div className="relative flex items-start gap-3 p-1.5 pl-4 bg-[#0e0e0e] border border-[rgba(218,220,224,0.15)] rounded-[16px] shadow-2xl overflow-hidden">
          <div className="flex-shrink-0 mt-3 text-[rgba(218,220,224,0.55)]">
            {isRefine ? <Sparkles size={16} strokeWidth={1.5} /> : <Wand2 size={16} strokeWidth={1.5} />}
          </div>

          <textarea
            ref={inputRef}
            rows={2}
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={isProcessing}
            className="flex-1 bg-transparent border-none text-[12px] font-medium text-white placeholder:text-[rgba(255,255,255,0.35)] focus:ring-0 py-2.5 outline-none tracking-[0.1px] resize-none"
          />

          <div className="flex items-center gap-1.5 flex-shrink-0 pr-2 mt-2">
            <button 
              onClick={() => { if (isAvailable) onConfirm(prompt); }}
              disabled={!isAvailable}
              className={`flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-medium uppercase tracking-widest transition-colors ${isAvailable ? 'bg-white/10 text-white hover:bg-white/20' : 'bg-white/5 text-[rgba(218,220,224,0.4)]'}`}
            >
              <CornerDownLeft size={10} />
              <span>Enter</span>
            </button>
            <button
              onClick={onClose}
              className="p-2 hover:bg-white/5 rounded-xl text-[rgba(218,220,224,0.4)] hover:text-white transition-all"
            >
              <X size={16} />
            </button>
          </div>
        </div>

        {!isRefine && !isOutpaint && (
          <div className="absolute -top-6 left-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <span className="text-[10px] font-medium uppercase tracking-[0.1px] text-[rgba(218,220,224,0.4)]">
              Inpainting: The AI generates content inside your mask
            </span>
          </div>
        )}

        {isOutpaint && (
          <div className="absolute -top-6 left-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <span className="text-[10px] font-medium uppercase tracking-[0.1px] text-[rgba(218,220,224,0.4)]">
              Outpainting: Expanding canvas environment
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Layer, LayerAdjustments, TextConfig } from '../types';
import { SectionLabel, PillButton, FieldDropdown, FieldDisplay, RangeSlider, SegmentedToggle, TextInput, SingleLineInput, NumberInput, ColorInput } from './UIPrimitives';
import { renderTextToDataUrl } from '../services/textService';
import { CANVAS_PRESETS } from '../constants';
import { Download, RotateCcw, Merge } from 'lucide-react';

interface PropertiesSidebarProps {
  layer: Layer | null;
  isTopmostLayer?: boolean;
  onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
  canvasWidth: number;
  canvasHeight: number;
  onUpdateCanvas: (width: number, height: number, markDirty?: boolean) => void;
  onResetCanvas: () => void;
  isAspectRatioLocked: boolean;
  onToggleAspectRatioLock: () => void;
  onCommitHistory: () => void;
  onSaveToGallery: () => void;
  onFlattenDepth?: (layerId: string) => void;
  isProcessing: boolean;
  aiModel: string;
  onAiModelChange: (model: string) => void;
  bgModel: string;
  onBgModelChange: (model: string) => void;
  onToggleDepthSort: (layerId: string, enabled: boolean) => void;
}

const FONTS = [
  'Google Sans', 'Inter', 'Bebas Neue', 'Montserrat', 'Playfair Display', 'Cinzel', 'Anton', 'Syne', 'Staatliches', 'Fraunces', 'Space Grotesk'
];

export const PropertiesSidebar: React.FC<PropertiesSidebarProps> = ({
  layer,
  isTopmostLayer = false,
  onUpdateLayer,
  canvasWidth,
  canvasHeight,
  onUpdateCanvas,
  onResetCanvas,
  isAspectRatioLocked,
  onToggleAspectRatioLock,
  onCommitHistory,
  onSaveToGallery,
  onFlattenDepth,
  isProcessing,
  aiModel,
  onAiModelChange,
  bgModel,
  onBgModelChange,
  onToggleDepthSort
}) => {
  const currentPreset = CANVAS_PRESETS.find(p => p.width === canvasWidth && p.height === canvasHeight);

  const handleUpdateText = (configUpdates: Partial<TextConfig>) => {
    if (!layer || !layer.textConfig) return;
    const newConfig = { ...layer.textConfig, ...configUpdates };

    onUpdateLayer(layer.id, { textConfig: newConfig });

    renderTextToDataUrl(newConfig).then(({ dataUrl, width, height }) => {
      onUpdateLayer(layer.id, { dataUrl, width, height });
    });
  };

  const handleAdjust = (updates: Partial<LayerAdjustments>) => {
    if (!layer) return;
    const adjustments = layer.adjustments || { brightness: 1, contrast: 1, saturation: 1, hueRotate: 0, blur: 0 };
    onUpdateLayer(layer.id, { adjustments: { ...adjustments, ...updates } });
  };

  return (
    <div className="relative border-l border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e]">
      <div className="flex flex-col gap-[24px] items-start w-full overflow-y-auto flex-1 scrollbar-hide pb-6">

        {!layer ? (
          <div className="flex flex-col gap-6 w-full">
            <div className="flex flex-col gap-2 items-start w-full">
              <SectionLabel>Canvas dimensions</SectionLabel>
              <div className="flex flex-col gap-1.5 w-full">
                <FieldDropdown 
                  label="Preset" 
                  value={currentPreset?.name || 'Custom'} 
                  options={[...CANVAS_PRESETS.map(p => p.name), 'Custom']}
                  onChange={(val) => {
                    const p = CANVAS_PRESETS.find(x => x.name === val);
                    if (p) {
                      onCommitHistory();
                      onUpdateCanvas(p.width, p.height);
                    }
                  }}
                />
                <div className="flex gap-1 w-full h-[49px]">
                  <NumberInput label="Width" value={canvasWidth} onChange={(w) => onUpdateCanvas(w || 1, canvasHeight)} className="flex-1" />
                  <NumberInput label="Height" value={canvasHeight} onChange={(h) => onUpdateCanvas(canvasWidth, h || 1)} className="flex-1" />
                </div>
                <PillButton variant="outline" onClick={onResetCanvas} icon={<RotateCcw size={18} strokeWidth={1.5} />}>
                  Reset defaults
                </PillButton>
              </div>
            </div>

            <div className="flex flex-col gap-2 items-start w-full">
              <SectionLabel>AI settings</SectionLabel>
              <div className="flex flex-col gap-1.5 w-full">
                <FieldDropdown
                  label="Image Model"
                  value={aiModel}
                  options={['Nano Banana 2', 'Nano Banana Pro']}
                  onChange={onAiModelChange}
                />
                <FieldDropdown
                  label="Background removal"
                  value={bgModel === 'Xenova/modnet' ? 'MODNet (People, Fast)' : 'BEN2 (General, Quality)'}
                  options={['MODNet (People, Fast)', 'BEN2 (General, Quality)']}
                  onChange={(val) => {
                    if (val === 'MODNet (People, Fast)') onBgModelChange('Xenova/modnet');
                    else onBgModelChange('onnx-community/BEN2-ONNX');
                  }}
                />
              </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col gap-3 w-full">
            {layer.id && layer.type === 'text' && layer.textConfig && (
              <div className="flex flex-col gap-1.5 w-full">
                <TextInput 
                    id="text-property-input"
                    value={layer.textConfig.content} 
                    onChange={(v) => handleUpdateText({ content: v })}
                    placeholder="Enter text..."
                  />
                  <div className="mt-2 mb-1">
                    <SectionLabel>Font</SectionLabel>
                  </div>
                  <FieldDropdown 
                    label="Font family" 
                    value={layer.textConfig.fontFamily} 
                    options={FONTS}
                    onChange={(v) => { onCommitHistory(); handleUpdateText({ fontFamily: v }); }}
                  />
                  <FieldDropdown 
                    label="Font weight" 
                    value={layer.textConfig.fontWeight || 'normal'} 
                    options={['lighter', 'normal', 'bold', 'bolder', '100', '200', '300', '400', '500', '600', '700', '800', '900']}
                    onChange={(v) => { onCommitHistory(); handleUpdateText({ fontWeight: v }); }}
                  />
                  <RangeSlider 
                    label="Line spacing" 
                    value={layer.textConfig.lineHeight || 1.2} 
                    min={0.5} max={3} step={0.1}
                    formatValue={v => `${v}x`}
                    onChange={v => handleUpdateText({ lineHeight: v })}
                  />
                  <RangeSlider 
                    label="Letter spacing" 
                    value={layer.textConfig.letterSpacing || 0} 
                    min={-10} max={50} step={1}
                    formatValue={v => `${v}px`}
                    onChange={v => handleUpdateText({ letterSpacing: v })}
                  />
                  <FieldDisplay label="Size" value={`${layer.textConfig.fontSize}px`} className="w-full" />
                  <ColorInput label="Color" value={layer.textConfig.color} onChange={e => handleUpdateText({ color: e })} />
                  <SegmentedToggle 
                    value={layer.textConfig.textAlign || 'left'}
                    onChange={(v) => { onCommitHistory(); handleUpdateText({ textAlign: v as any }); }}
                    items={[
                      { value: 'left', label: 'Left' },
                      { value: 'center', label: 'Center' },
                      { value: 'right', label: 'Right' },
                    ]}
                  />
              </div>
            )}

            <div className="flex flex-col gap-1.5 w-full">
              <RangeSlider 
                  label="Opacity" 
                  value={layer.opacity} 
                  min={0} max={1} step={0.01} 
                  formatValue={v => `${Math.round(v * 100)}%`}
                  onChange={v => onUpdateLayer(layer.id, { opacity: v })}
