              {layer.type === 'image' && (
                <>
                  <RangeSlider 
                    label="Brightness" 
                    value={layer.adjustments?.brightness ?? 1} 
                    min={0} max={2} step={0.01}
                    onChange={v => handleAdjust({ brightness: v })}
                  />
                  <RangeSlider 
                    label="Contrast" 
                    value={layer.adjustments?.contrast ?? 1} 
                    min={0} max={2} step={0.01}
                    onChange={v => handleAdjust({ contrast: v })}
                  />
                  <RangeSlider 
                    label="Saturation" 
                    value={layer.adjustments?.saturation ?? 1} 
                    min={0} max={2} step={0.01}
                    onChange={v => handleAdjust({ saturation: v })}
                  />
                  <RangeSlider 
                    label="Blur" 
                    value={layer.adjustments?.blur ?? 0} 
                    min={0} max={20} step={0.5}
                    formatValue={v => `${v}px`}
                    onChange={v => handleAdjust({ blur: v })}
                  />
                </>
              )}
              </div>

            {(isTopmostLayer || layer.depthEnabled) && (
              <div className="flex flex-col gap-1.5 w-full pt-1.5 border-t border-white/5">
                  {!isTopmostLayer && layer.depthEnabled && (
                    <div className="px-2 py-1 bg-red-500/10 border border-red-500/20 rounded-lg text-[10px] text-red-400 mb-1 leading-tight">
                      This layer must be moved to the top (front) for AI Z-Depth to process effectively.
                    </div>
                  )}
                  <div className={`flex items-center justify-between px-2 pt-2 pb-[3px]`}>
