    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, Maximize, Loader2, Crop, Check, X, UserMinus, Undo2, Redo2, Brush } from 'lucide-react';
import { PillButton } from './UIPrimitives';

interface ToolbarProps {
  isProcessing: boolean;
  processingMessage?: string | null;
  processingProgress?: number;
  isOutpainting: boolean;
  isCropping: boolean;
  isInpainting: boolean;
  promptMode: 'refine' | 'inpaint' | 'outpaint' | null;
  canUndo: boolean;
  canRedo: boolean;
  onUndo: () => void;
  onRedo: () => void;
  onRefine: () => void;
  onOutpaint: () => void;
  onInpaint: () => void;
  onStartCrop: () => void;
  onApplyCrop: () => void;
  onCancelCrop: () => void;
  onRemoveBackground: () => void;
}

export const Toolbar: React.FC<ToolbarProps> = ({ 
  isProcessing, 
  processingMessage,
  processingProgress = 0,
  isOutpainting,
  isCropping,
  isInpainting,
  promptMode,
  canUndo,
  canRedo,
  onUndo,
  onRedo,
  onRefine, 
  onOutpaint, 
  onInpaint,
  onStartCrop,
  onApplyCrop,
  onCancelCrop,
  onRemoveBackground,
}) => {
  const isBusy = isProcessing;
  const toolbarRef = useRef<HTMLDivElement>(null);
  const [isCompact, setIsCompact] = useState(false);

  useEffect(() => {
    if (!toolbarRef.current) return;

    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setIsCompact(entry.contentRect.width < 520);
      }
    });

    observer.observe(toolbarRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={toolbarRef} className="relative flex flex-col items-center">
      {/* Floating Status Pill */}
      {isProcessing && processingMessage && processingMessage !== 'Generating...' && (
        <div className="absolute -top-[52px] left-1/2 -translate-x-1/2 bg-[#0e0e0e] border border-[rgba(218,220,224,0.15)] shadow-xl rounded-full pl-3 pr-4 py-2 flex items-center gap-3 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <Loader2 size={16} className="text-[rgba(218,220,224,0.8)] animate-spin" />
          <div className="flex items-center gap-2">
            <span className="text-[12px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] whitespace-nowrap">
              {processingMessage}
            </span>
            {processingProgress > 0 && processingProgress < 100 && (
              <div className="flex items-center gap-2">
                <div className="h-1.5 bg-white/10 rounded-full w-16 overflow-hidden">
                  <div className="h-full bg-white/80 transition-all duration-200" style={{ width: `${processingProgress}%` }} />
                </div>
                <span className="text-[10px] text-[rgba(218,220,224,0.5)] font-mono tracking-tighter w-5 text-right">{processingProgress}%</span>
              </div>
            )}
          </div>
        </div>
      )}

      <div className={`flex items-center gap-1.5 p-[10px] bg-[#0e0e0e] border border-[rgba(218,220,224,0.15)] rounded-[16px] shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500 relative ${isCompact ? 'min-w-0' : 'min-w-[500px]'}`}>
      <div className="flex items-center gap-1 pr-1.5 border-r border-white/10">
        <button
          onClick={onUndo}
          disabled={!canUndo || isBusy}
          className="w-8 h-8 rounded-lg flex items-center justify-center text-[rgba(218,220,224,0.55)] hover:text-white hover:bg-white/5 disabled:opacity-20 transition-all"
        >
          <Undo2 size={16} />
        </button>
        <button
          onClick={onRedo}
          disabled={!canRedo || isBusy}
          className="w-8 h-8 rounded-lg flex items-center justify-center text-[rgba(218,220,224,0.55)] hover:text-white hover:bg-white/5 disabled:opacity-20 transition-all"
        >
          <Redo2 size={16} />
        </button>
      </div>

      <div className="flex-1 flex items-center gap-1.5 overflow-x-auto scrollbar-hide h-[34px]">
        {isCropping ? (
          <div className="flex items-center gap-1.5 w-full">
            {!isCompact && (
              <span className="text-[11px] font-medium text-[rgba(218,220,224,0.5)] uppercase tracking-[0.1px] px-2 border-r border-white/10 mr-1">
                Cropping
              </span>
            )}
            <PillButton variant="solid" onClick={onApplyCrop} disabled={isProcessing} icon={<Check size={16} />} hideLabel={isCompact}>Apply</PillButton>
            <PillButton variant="outline" onClick={onCancelCrop} disabled={isProcessing} icon={<X size={16} />} hideLabel={isCompact}>Cancel</PillButton>
          </div>
        ) : (
          <>
            <div className={`${isCompact ? 'min-w-0' : 'min-w-[100px]'} relative`}>
              <PillButton variant={promptMode === 'refine' ? 'filled' : 'outline'} onClick={onRefine} disabled={isBusy || isCropping} icon={isBusy && promptMode === 'refine' ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} strokeWidth={1.5} />} hideLabel={isCompact}>Refine</PillButton>
            </div>
            <div className={`${isCompact ? 'min-w-0' : 'min-w-[100px]'} relative`}>
              <PillButton variant={isInpainting ? 'filled' : 'outline'} onClick={onInpaint} disabled={isBusy || isCropping} icon={isBusy && promptMode === 'inpaint' ? <Loader2 size={16} className="animate-spin" /> : <Brush size={16} strokeWidth={1.5} />} hideLabel={isCompact}>Inpaint</PillButton>
            </div>
            <div className={`${isCompact ? 'min-w-0' : 'min-w-[100px]'} relative`}>
              <PillButton variant={isOutpainting ? 'filled' : 'outline'} onClick={onOutpaint} disabled={isBusy || isCropping} icon={isBusy && promptMode === 'outpaint' ? <Loader2 size={16} className="animate-spin" /> : <Maximize size={16} strokeWidth={1.5} />} hideLabel={isCompact}>Outpaint</PillButton>
            </div>
            <div className={`${isCompact ? 'min-w-0' : 'min-w-[100px]'} relative`}>
              <PillButton variant="outline" onClick={onRemoveBackground} disabled={isBusy || isCropping} icon={isBusy && processingMessage?.includes('background') ? <Loader2 size={16} className="animate-spin" /> : <UserMinus size={16} strokeWidth={1.5} />} hideLabel={isCompact}>Cutout</PillButton>
            </div>
            <div className={`${isCompact ? 'min-w-0' : 'min-w-[100px]'} relative`}>
              <PillButton variant="outline" onClick={onStartCrop} disabled={isBusy || isCropping} icon={<Crop size={16} strokeWidth={1.5} />} hideLabel={isCompact}>Crop</PillButton>
            </div>
          </>
        )}
      </div>
    </div>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';
import { Layer, Point } from '../types';
import { RotateCw, FlipHorizontal, FlipVertical } from 'lucide-react';
import { renderTextToDataUrl } from '../services/textService';

interface TransformOverlayProps {
  activeLayer: Layer;
  zoom: number;
  offset: Point;
  canvasWidth: number;
  canvasHeight: number;
  onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
  getWorldMouse: (clientX: number, clientY: number) => Point;
  onCommitHistory: () => void;
  onDoubleClick?: () => void;
}

type TransformMode = 'none' | 'translate' | 'rotate' | 
  'scale-nw' | 'scale-ne' | 'scale-sw' | 'scale-se' |
  'scale-n' | 'scale-s' | 'scale-e' | 'scale-w';

export const TransformOverlay: React.FC<TransformOverlayProps> = ({
  activeLayer,
  zoom,
  offset,
  canvasWidth,
  canvasHeight,
  onUpdateLayer,
  getWorldMouse,
  onCommitHistory,
  onDoubleClick
}) => {
  const interactionRef = useRef<{
    mode: TransformMode;
    initialState: any;
  }>({ mode: 'none', initialState: null });

  const handleStart = (e: React.PointerEvent, mode: TransformMode) => {
    e.stopPropagation();
    const target = e.currentTarget as HTMLElement;
    target.setPointerCapture(e.pointerId);

    const worldMouse = getWorldMouse(e.clientX, e.clientY);
    const rad = (activeLayer.rotation * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);

    let signX = 0, signY = 0;
    if (mode === 'scale-nw') { signX = -1; signY = -1; }
    else if (mode === 'scale-ne') { signX = 1; signY = -1; }
    else if (mode === 'scale-sw') { signX = -1; signY = 1; }
    else if (mode === 'scale-se') { signX = 1; signY = 1; }
    else if (mode === 'scale-n') { signY = -1; }
    else if (mode === 'scale-s') { signY = 1; }
    else if (mode === 'scale-e') { signX = 1; }
    else if (mode === 'scale-w') { signX = -1; }

    const currentW = activeLayer.width * activeLayer.scale;
    const currentH = activeLayer.height * activeLayer.scale;

    const localPivotX = -signX * (currentW / 2);
    const localPivotY = -signY * (currentH / 2);

    const pivot = {
      x: activeLayer.x + (localPivotX * cos - localPivotY * sin),
      y: activeLayer.y + (localPivotX * sin + localPivotY * cos)
    };

    interactionRef.current = {
      mode,
      initialState: {
        id: activeLayer.id,
        pivot,
        w: currentW,
        h: currentH,
        x: activeLayer.x,
        y: activeLayer.y,
        rotation: activeLayer.rotation,
        startMouse: worldMouse,
        startAngle: Math.atan2(worldMouse.y - activeLayer.y, worldMouse.x - activeLayer.x) * (180 / Math.PI),
        signX,
        signY,
        layer: activeLayer // Store full layer to access textConfig and original size
      }
    };
  };

  useEffect(() => {
    const handleMove = (e: PointerEvent) => {
      const { mode, initialState } = interactionRef.current;
      if (mode === 'none' || !initialState) return;

      const worldMouse = getWorldMouse(e.clientX, e.clientY);
      const rad = (initialState.rotation * Math.PI) / 180;
      const cos = Math.cos(rad);
      const sin = Math.sin(rad);

      if (mode === 'translate') {
        const dx = worldMouse.x - initialState.startMouse.x;
        const dy = worldMouse.y - initialState.startMouse.y;

        let newX = initialState.x + dx;
        let newY = initialState.y + dy;

        const snapThreshold = 12 / zoom;
        const halfW = initialState.w / 2;
        const halfH = initialState.h / 2;

        if (Math.abs((newX - halfW) - 0) < snapThreshold) newX = halfW;
        else if (Math.abs((newX + halfW) - canvasWidth) < snapThreshold) newX = canvasWidth - halfW;
        else if (Math.abs(newX - canvasWidth / 2) < snapThreshold) newX = canvasWidth / 2;

        if (Math.abs((newY - halfH) - 0) < snapThreshold) newY = halfH;
        else if (Math.abs((newY + halfH) - canvasHeight) < snapThreshold) newY = canvasHeight - halfH;
        else if (Math.abs(newY - canvasHeight / 2) < snapThreshold) newY = canvasHeight / 2;

        onUpdateLayer(initialState.id, { x: newX, y: newY });
      } 
      else if (mode === 'rotate') {
        const currentAngle = Math.atan2(worldMouse.y - initialState.y, worldMouse.x - initialState.x) * (180 / Math.PI);
        onUpdateLayer(initialState.id, { rotation: (initialState.rotation + (currentAngle - initialState.startAngle)) % 360 });
      } 
      else if (mode.startsWith('scale-')) {
        const dx = worldMouse.x - initialState.pivot.x;
        const dy = worldMouse.y - initialState.pivot.y;
        const localDx = dx * cos + dy * sin;
        const localDy = -dx * sin + dy * cos;

        let newW = Math.max(20, localDx * initialState.signX);
        let newH = Math.max(20, localDy * initialState.signY);

        if (initialState.signX !== 0 && initialState.signY !== 0) {
          const aspect = initialState.w / initialState.h;
          if (newW / newH > aspect) newW = newH * aspect;
          else newH = newW / aspect;
        }

        if (initialState.signX === 0) newW = initialState.w;
        if (initialState.signY === 0) newH = initialState.h;

        const localCenterX = (initialState.signX * newW) / 2;
        const localCenterY = (initialState.signY * newH) / 2;
        const newX = initialState.pivot.x + (localCenterX * cos - localCenterY * sin);
        const newY = initialState.pivot.y + (localCenterX * sin + localCenterY * cos);

        onUpdateLayer(initialState.id, { x: newX, y: newY, width: newW, height: newH, scale: 1 });
      }
    };

    const handleUp = () => {
      const { mode, initialState } = interactionRef.current;
      if (mode === 'none') return;

      onCommitHistory();

      interactionRef.current = { mode: 'none', initialState: null }; 
    };

    window.addEventListener('pointermove', handleMove);
    window.addEventListener('pointerup', handleUp);
    return () => {
      window.removeEventListener('pointermove', handleMove);
      window.removeEventListener('pointerup', handleUp);
    };
  }, [onUpdateLayer, getWorldMouse, canvasWidth, canvasHeight, zoom, activeLayer, onCommitHistory]);

  const handles = [
    { mode: 'scale-nw', pos: '-top-2.5 -left-2.5', cursor: 'nwse-resize' },
    { mode: 'scale-ne', pos: '-top-2.5 -right-2.5', cursor: 'nesw-resize' },
    { mode: 'scale-sw', pos: '-bottom-2.5 -left-2.5', cursor: 'nesw-resize' },
    { mode: 'scale-se', pos: '-bottom-2.5 -right-2.5', cursor: 'nwse-resize' },
    { mode: 'scale-n', pos: '-top-2.5 left-1/2 -translate-x-1/2', cursor: 'ns-resize' },
    { mode: 'scale-s', pos: '-bottom-2.5 left-1/2 -translate-x-1/2', cursor: 'ns-resize' },
    { mode: 'scale-e', pos: 'top-1/2 -right-2.5 -translate-y-1/2', cursor: 'ew-resize' },
    { mode: 'scale-w', pos: 'top-1/2 -left-2.5 -translate-y-1/2', cursor: 'ew-resize' },
  ];

  return (
    <div
      className="absolute select-none z-[300] pointer-events-none"
      style={{
        left: activeLayer.x,
        top: activeLayer.y,
        width: activeLayer.width * activeLayer.scale,
        height: activeLayer.height * activeLayer.scale,
        transform: `translate(-50%, -50%) rotate(${activeLayer.rotation}deg)`,
      }}
    >
      <div className="absolute inset-0 ring-2 ring-white/80 shadow-[0_0_30px_rgba(0,0,0,0.7)] pointer-events-none" />
      <div className="absolute inset-0 cursor-move pointer-events-auto" onPointerDown={(e) => handleStart(e, 'translate')} onDoubleClick={(e) => { e.stopPropagation(); onDoubleClick?.(); }} />
      {handles.map((h) => (
        <div key={h.mode} onPointerDown={(e) => handleStart(e, h.mode as any)} style={{ cursor: h.cursor }} className={`absolute w-5 h-5 bg-white border-2 border-zinc-950 pointer-events-auto rounded-full hover:scale-125 transition-transform z-[310] ${h.pos} shadow-2xl`} />
      ))}
      <div className="absolute -top-16 left-1/2 -translate-x-1/2 flex items-center gap-4 pointer-events-none z-[310]">
        <button onClick={(e) => { e.stopPropagation(); onCommitHistory(); onUpdateLayer(activeLayer.id, { flipX: !activeLayer.flipX }); }} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-2xl pointer-events-auto border-2 border-zinc-950 hover:scale-110 active:scale-95 ${activeLayer.flipX ? 'bg-white text-black' : 'bg-zinc-900 text-white hover:bg-zinc-800'}`} title="Flip Horizontal"><FlipHorizontal size={18} /></button>
        <div onPointerDown={(e) => handleStart(e, 'rotate')} className="w-12 h-12 bg-white text-black rounded-full flex items-center justify-center cursor-grab active:cursor-grabbing shadow-2xl pointer-events-auto border-2 border-zinc-950 hover:scale-110 transition-transform" title="Rotate"><RotateCw size={22} /></div>
        <button onClick={(e) => { e.stopPropagation(); onCommitHistory(); onUpdateLayer(activeLayer.id, { flipY: !activeLayer.flipY }); }} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-2xl pointer-events-auto border-2 border-zinc-950 hover:scale-110 active:scale-95 ${activeLayer.flipY ? 'bg-white text-black' : 'bg-zinc-900 text-white hover:bg-zinc-800'}`} title="Flip Vertical"><FlipVertical size={18} /></button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown } from 'lucide-react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[12px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
      {children}
    </span>
