export const PillButton: React.FC<{
  icon?: React.ReactNode;
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid';
  onClick?: () => void;
  disabled?: boolean;
  hideLabel?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled, hideLabel }) => {
  const base = 'flex items-center gap-[2px] justify-center h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';

  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] select-none shadow-sm',
  };

  const padding = hideLabel 
    ? 'px-2.5' 
    : variant === 'filled' 
      ? 'pl-[8px] pr-[24px] py-1' 
      : 'pl-[8px] pr-[16px] py-2';

  const widthClass = hideLabel ? '' : 'w-full';

  return (
    <button 
      className={`${base} ${variants[variant]} ${padding} ${widthClass}`} 
      onClick={onClick} 
      disabled={disabled}
      title={hideLabel ? String(children) : undefined}
    >
      {icon && <span className="w-6 h-6 flex items-center justify-center">{icon}</span>}
      {!hideLabel && <span>{children}</span>}
    </button>
  );
};

function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchstart', listener);
    };
  }, [ref, handler]);
}

