import React, { useState, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Camera, X, RefreshCw, Check, Loader2 } from 'lucide-react';

interface WebcamModalProps {
  isOpen: boolean;
  onClose: () => void;
  onCapture: (dataUrl: string) => void;
}

export const WebcamModal: React.FC<WebcamModalProps> = ({ isOpen, onClose, onCapture }) => {
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isCapturing, setIsCapturing] = useState(false);
  const [isStreamActive, setIsStreamActive] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<any>(null);

  useEffect(() => {
    if (isOpen) {
      startStream();
    } else {
      stopStream();
    }
    return () => stopStream();
  }, [isOpen]);

  const startStream = async () => {
    setError(null);
    try {
      const stream = await Flow.camera.stream({ facingMode: 'user', resolution: 'high' });
      streamRef.current = stream;
      setIsStreamActive(true);

      const canvas = canvasRef.current;
      if (canvas) {
        canvas.width = stream.width;
        canvas.height = stream.height;
      }
      const ctx = canvas?.getContext('2d');

      stream.onFrame(({ bitmap, width, height }: any) => {
        if (ctx && canvas) {
          ctx.drawImage(bitmap, 0, 0, width, height);
        }
        bitmap.close();
      });
    } catch (err) {
      console.error("Camera stream error:", err);
      setError("Could not access camera. Please check permissions.");
    }
  };

  const stopStream = async () => {
    if (streamRef.current) {
      await streamRef.current.stop();
      streamRef.current = null;
      setIsStreamActive(false);
    }
  };

  const capture = async () => {
    if (!canvasRef.current) return;
    setIsCapturing(true);
    try {
      // Use standard capture or just take current canvas state
      const dataUrl = canvasRef.current.toDataURL('image/png');
      setCapturedImage(dataUrl);
      stopStream();
    } catch (err) {
      console.error("Capture error:", err);
      setError("Failed to capture image.");
    } finally {
      setIsCapturing(false);
    }
  };

  const handleRetake = () => {
    setCapturedImage(null);
    setError(null);
    startStream();
  };

  const handleClose = () => {
    setCapturedImage(null);
    setError(null);
    stopStream();
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="w-full max-w-2xl bg-[#0e0e0e] border border-white/10 rounded-[32px] shadow-2xl overflow-hidden flex flex-col">
        <div className="p-5 border-b border-white/5 flex items-center justify-between bg-white/5">
          <div className="flex items-center gap-2.5 font-bold text-white tracking-tight">
            <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center">
              <Camera size={16} className="text-white/80" />
            </div>
            <span>Camera Capture</span>
          </div>
          <button onClick={handleClose} className="p-2 hover:bg-white/10 rounded-full text-white/40 hover:text-white transition-all">
            <X size={20} />
          </button>
        </div>

        <div className="relative aspect-video bg-black flex items-center justify-center overflow-hidden">
          {error ? (
            <div className="text-center p-8 max-w-sm space-y-5">
              <div className="w-16 h-16 rounded-2xl bg-red-500/10 flex items-center justify-center mx-auto border border-red-500/20">
                 <X size={32} className="text-red-400" />
              </div>
              <p className="text-red-400 text-[13px] font-medium leading-relaxed">{error}</p>
              <button onClick={startStream} className="w-full h-11 bg-white/10 hover:bg-white/20 rounded-xl text-[12px] font-bold uppercase tracking-widest text-white transition-all">Try Again</button>
            </div>
          ) : capturedImage ? (
            <img src={capturedImage} className="w-full h-full object-contain animate-in zoom-in-95 duration-300" alt="Captured" />
          ) : (
            <div className="relative w-full h-full flex items-center justify-center">
              <canvas
                ref={canvasRef}
                className={`w-full h-full object-contain transition-opacity duration-700 ${isStreamActive ? 'opacity-100' : 'opacity-0'}`}
              />
              {!isStreamActive && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-white/20">
                  <Loader2 size={32} className="animate-spin" />
                  <span className="text-[10px] font-bold uppercase tracking-[0.2em]">Initializing Feed</span>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="p-8 bg-white/5 flex items-center justify-center gap-4">
          {!capturedImage ? (
            <button
              onClick={capture}
              disabled={isCapturing || !isStreamActive}
              className="group relative w-20 h-20 rounded-full bg-white flex items-center justify-center shadow-2xl hover:scale-105 active:scale-95 transition-all disabled:opacity-20 disabled:grayscale"
            >
              <div className="w-16 h-16 rounded-full border-4 border-black/10 group-hover:border-black/20 transition-colors" />
            </button>
          ) : (
            <div className="flex gap-3 w-full max-w-md">
              <button
                onClick={handleRetake}
                className="flex-1 flex items-center justify-center gap-2 h-14 bg-white/5 hover:bg-white/10 text-white rounded-2xl font-bold transition-all border border-white/10"
              >
                <RefreshCw size={18} />
                <span>Retake</span>
              </button>
              <button
                onClick={() => onCapture(capturedImage)}
                className="flex-1 flex items-center justify-center gap-2 h-14 bg-white hover:bg-zinc-100 text-black rounded-2xl font-bold transition-all shadow-xl"
              >
                <Check size={18} />
                <span>Add Layer</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { env, pipeline, RawImage } from '@huggingface/transformers';

// Fix for sandboxed environments where Cache API is disabled
env.allowLocalModels = false;
env.useBrowserCache = false; 

let bgRemoverInstances: Record<string, any> = {};

export type BgProgressEvent = {
  status: 'init' | 'downloading' | 'processing' | 'done';
  progress?: number;
  filename?: string;
};

export const initBgRemover = async (modelId: string, onProgress?: (progress: BgProgressEvent) => void) => {
  if (bgRemoverInstances[modelId]) return bgRemoverInstances[modelId];

  const hasWebGPU = !!navigator.gpu;
  const device = hasWebGPU ? 'webgpu' : 'wasm';
  let dtype = hasWebGPU ? 'fp16' : 'q8';

  if (modelId === 'Xenova/modnet') {
     dtype = hasWebGPU ? 'fp32' : 'q8';
  }

  console.log(`Initializing ${modelId} with device=${device}, dtype=${dtype}`);

  bgRemoverInstances[modelId] = await pipeline('background-removal', modelId, {
    device: device,
    dtype: dtype as any,
    progress_callback: (data: any) => {
      if (data.status === 'initiate' || data.status === 'download') {
        if (onProgress) onProgress({ status: 'init', filename: data.name });
      } else if (data.status === 'progress') {
        if (onProgress) onProgress({ status: 'downloading', progress: data.progress, filename: data.file });
      } else if (data.status === 'done') {
        if (onProgress) onProgress({ status: 'done', filename: data.file });
      }
    },
  });

  return bgRemoverInstances[modelId];
};

export const removeBackground = async (imageSrc: string, modelId: string = 'Xenova/modnet', onProgress?: (p: BgProgressEvent) => void) => {
  const remover = await initBgRemover(modelId, onProgress);

  if (onProgress) onProgress({ status: 'processing' });

  const inImg = new Image();
  inImg.crossOrigin = "anonymous";
  inImg.src = imageSrc;
  await new Promise((resolve, reject) => {
    inImg.onload = resolve;
    inImg.onerror = reject;
  });

  let w = inImg.width;
  let h = inImg.height;
  const MAX_DIM = 768; 
  if (w > MAX_DIM || h > MAX_DIM) {
    const scale = Math.min(MAX_DIM / w, MAX_DIM / h);
    w = Math.floor(w * scale);
    h = Math.floor(h * scale);
  }

  const inCanvas = document.createElement('canvas');
  inCanvas.width = w;
  inCanvas.height = h;
  const inCtx = inCanvas.getContext('2d')!;
  inCtx.drawImage(inImg, 0, 0, w, h);
  const resizedSrc = inCanvas.toDataURL('image/png');

  const img = await RawImage.fromURL(resizedSrc);

  let output = await remover(img);
  if (Array.isArray(output)) {
    output = output[0];
  }

  const canvas = document.createElement('canvas');
  canvas.width = output.width;
  canvas.height = output.height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Could not get canvas context');

  const imageData = ctx.createImageData(output.width, output.height);
  imageData.data.set(output.data);
  ctx.putImageData(imageData, 0, 0);

  return canvas.toDataURL('image/png');
};

/**
 * Depth Anything V2 - Web Implementation
 * 
 * Dependencies: 
 * - onnxruntime-web (global 'ort' variable from CDN)
 */

import { pipeline, RawImage } from '@huggingface/transformers';

let depthPipeline: any = null;

export async function estimateDepth(src: string, resolution: number = 518, onProgress?: (progress: number) => void): Promise<string> {
    if (!depthPipeline) {
        console.log("Loading Depth pipeline...");
        const hasWebGPU = !!navigator.gpu;
        depthPipeline = await pipeline('depth-estimation', 'onnx-community/depth-anything-v2-small', {
            device: hasWebGPU ? 'webgpu' : 'wasm',
            dtype: hasWebGPU ? 'fp16' : 'q8',
            progress_callback: (data: any) => {
                if (data.status === 'progress' && onProgress) {
                    onProgress(data.progress || 0);
                }
            }
        });
    }

    const image = await RawImage.fromURL(src);
    // Downscale if image is too large to prevent memory issues
    let w = image.width;
    let h = image.height;
    const MAX_DIM = 768; // For depth estimation, lower resolution is fine and avoids memory errors
    if (w > MAX_DIM || h > MAX_DIM) {
      const scale = Math.min(MAX_DIM / w, MAX_DIM / h);
      w = Math.floor(w * scale);
      h = Math.floor(h * scale);
    }

    const resizedImage = await image.resize(w, h);

    // The pipeline returns { predicted_depth: Tensor, depth: RawImage }
    const result = await depthPipeline(resizedImage);

    // result.depth is a RawImage instance
    const depthImage = result.depth;

    // We need to return a Data URL, so we convert the RawImage to a Canvas
    const canvas = document.createElement('canvas');
    canvas.width = depthImage.width;
    canvas.height = depthImage.height;
    const ctx = canvas.getContext('2d')!;

    const imageData = ctx.createImageData(depthImage.width, depthImage.height);
    const numPixels = depthImage.width * depthImage.height;
    const inData = depthImage.data;

    // RawImage from depth returned is usually 1 channel (grayscale) or 3 channels (rgb)
    if (inData.length === numPixels) {
      for (let i = 0; i < numPixels; i++) {
        imageData.data[i * 4] = inData[i];
        imageData.data[i * 4 + 1] = inData[i];
        imageData.data[i * 4 + 2] = inData[i];
        imageData.data[i * 4 + 3] = 255;
      }
    } else if (inData.length === numPixels * 3) {
      for (let i = 0; i < numPixels; i++) {
        imageData.data[i * 4] = inData[i * 3];
        imageData.data[i * 4 + 1] = inData[i * 3 + 1];
        imageData.data[i * 4 + 2] = inData[i * 3 + 2];
        imageData.data[i * 4 + 3] = 255;
      }
    } else {
      imageData.data.set(new Uint8ClampedArray(inData));
    }

    ctx.putImageData(imageData, 0, 0);

    // upscale back to original size for the final mask
    const finalCanvas = document.createElement("canvas");
    finalCanvas.width = image.width;
    finalCanvas.height = image.height;
    const finalCtx = finalCanvas.getContext("2d")!;
    finalCtx.drawImage(canvas, 0, 0, image.width, image.height);

    return finalCanvas.toDataURL('image/png');
}

import { Layer } from '../types';

export const computeDepthMask = async (
  layer: Layer,
  bgDepthUrl: string,
  fgDepthUrl: string,
  canvasWidth: number,
  canvasHeight: number,
  bgCompositeUrl?: string
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const bgImg = new Image();
    const fgImg = new Image();
    const origImg = new Image();
    const bgCompImg = new Image();

    const hasBgComp = !!bgCompositeUrl;
    let loadedCount = 0;
    const totalToLoad = hasBgComp ? 4 : 3;

    const onLoad = () => {
      loadedCount++;
      if (loadedCount === totalToLoad) {
        try {
          const result = processMask();
          resolve(result);
        } catch(e) {
          reject(e);
        }
      }
    };

    bgImg.onload = onLoad;
    fgImg.onload = onLoad;
    origImg.onload = onLoad;
    bgCompImg.onload = onLoad;
    bgImg.onerror = reject;
    fgImg.onerror = reject;
    origImg.onerror = reject;
    bgCompImg.onerror = reject;

    bgImg.src = bgDepthUrl;
    fgImg.src = fgDepthUrl;
    origImg.src = layer.dataUrl;
    if (hasBgComp) bgCompImg.src = bgCompositeUrl!;

    function processMask() {
      // 1. Align background depth to foreground's local space
      const alignCanvas = document.createElement('canvas');
      alignCanvas.width = layer.width;
      alignCanvas.height = layer.height;
      const alignCtx = alignCanvas.getContext('2d', { willReadFrequently: true })!;

      alignCtx.save();
      alignCtx.translate(layer.width / 2, layer.height / 2);
      alignCtx.scale(1 / layer.scale, 1 / layer.scale);
      alignCtx.rotate(-layer.rotation * Math.PI / 180);
      alignCtx.translate(-layer.x, -layer.y);
      alignCtx.drawImage(bgImg, 0, 0, canvasWidth, canvasHeight);
      alignCtx.restore();

      const alignedBgData = alignCtx.getImageData(0, 0, layer.width, layer.height).data;

      // 1b. Align background composite to foreground's local space (Problem 1 Fix)
      let alignedBgCompData: Uint8ClampedArray | null = null;
      if (hasBgComp) {
        alignCtx.clearRect(0, 0, layer.width, layer.height);
        alignCtx.save();
        alignCtx.translate(layer.width / 2, layer.height / 2);
        alignCtx.scale(1 / layer.scale, 1 / layer.scale);
        alignCtx.rotate(-layer.rotation * Math.PI / 180);
        alignCtx.translate(-layer.x, -layer.y);
        alignCtx.drawImage(bgCompImg, 0, 0, canvasWidth, canvasHeight);
        alignCtx.restore();
        alignedBgCompData = alignCtx.getImageData(0, 0, layer.width, layer.height).data;
      }

      // 2. Get foreground depth data
      const fgCanvas = document.createElement('canvas');
      fgCanvas.width = layer.width;
      fgCanvas.height = layer.height;
      const fgCtx = fgCanvas.getContext('2d', { willReadFrequently: true })!;
      fgCtx.drawImage(fgImg, 0, 0, layer.width, layer.height);
      const fgData = fgCtx.getImageData(0, 0, layer.width, layer.height).data;

      // 2.5 Get original alpha
      const origCanvas = document.createElement('canvas');
      origCanvas.width = layer.width;
      origCanvas.height = layer.height;
      const origCtx = origCanvas.getContext('2d', { willReadFrequently: true })!;
      origCtx.drawImage(origImg, 0, 0, layer.width, layer.height);
      const origData = origCtx.getImageData(0, 0, layer.width, layer.height).data;

      // 3. Optional flattening
      let flattenedDepth = -1;
      if (layer.flattenDepth) {
        let sumDepth = 0;
        let count = 0;
        for (let i = 0; i < fgData.length; i += 4) {
          if (origData[i+3] > 128) {
            sumDepth += fgData[i];
            count++;
          }
        }
        flattenedDepth = count > 0 ? Math.round(sumDepth / count) : 0;
      }

      // 4. Generate Mask
      const maskCanvas = document.createElement('canvas');
      maskCanvas.width = layer.width;
      maskCanvas.height = layer.height;
      const maskCtx = maskCanvas.getContext('2d')!;
      const maskImageData = maskCtx.createImageData(layer.width, layer.height);
      const maskData = maskImageData.data;

      const offset = layer.depthOffset || 0;

      for (let i = 0; i < fgData.length; i += 4) {
        // Problem 1 Fix: Absolute far depth for empty space
        if (alignedBgData[i+3] === 0 || (alignedBgCompData && alignedBgCompData[i+3] < 10)) {
           maskData[i] = 0;
           maskData[i+1] = 0;
           maskData[i+2] = 0;
           maskData[i+3] = 255; // Foreground always visible over emptiness
           continue;
        }

        const bgVal = alignedBgData[i];
        const fgValRaw = layer.flattenDepth ? flattenedDepth : fgData[i];

        const fgVal = fgValRaw + offset;
        const diff = fgVal - bgVal;

        let alpha = 0;
        if (diff > 5) alpha = 255;
        else if (diff < -5) alpha = 0;
        else {
           alpha = Math.floor(128 + (diff / 5) * 127);
        }

        maskData[i] = 0;
        maskData[i+1] = 0;
        maskData[i+2] = 0;
        maskData[i+3] = alpha;
      }

      maskCtx.putImageData(maskImageData, 0, 0);
      return maskCanvas.toDataURL('image/png');
    }
  });
};

import { Layer } from '../types';

export const compositeToCanvas = async (layers: Layer[], canvasWidth: number, canvasHeight: number, backgroundColor: string = 'black'): Promise<HTMLCanvasElement> => {
  const canvas = document.createElement('canvas');
  canvas.width = canvasWidth;
  canvas.height = canvasHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Could not get canvas context');

  if (backgroundColor !== 'transparent') {
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);
  }

  const sortedLayers = [...layers]
    .filter(l => l.visible)
    .sort((a, b) => a.zIndex - b.zIndex);

  for (const layer of sortedLayers) {
    try {
      const img = await loadImage(layer.dataUrl);
      const finalWidth = layer.width * layer.scale;
      const finalHeight = layer.height * layer.scale;

      const layerTempCanvas = document.createElement('canvas');
      layerTempCanvas.width = finalWidth;
      layerTempCanvas.height = finalHeight;
      const lCtx = layerTempCanvas.getContext('2d');
      if (!lCtx) continue;

      // Apply adjustments if present
      if (layer.adjustments) {
        const { brightness, contrast, saturation, hueRotate, blur } = layer.adjustments;
        lCtx.filter = `brightness(${brightness}) contrast(${contrast}) saturate(${saturation}) hue-rotate(${hueRotate}deg) blur(${blur}px)`;
      }

      lCtx.save();
      lCtx.translate(finalWidth / 2, finalHeight / 2);
      lCtx.scale(layer.flipX ? -1 : 1, layer.flipY ? -1 : 1);
      lCtx.drawImage(img, -finalWidth / 2, -finalHeight / 2, finalWidth, finalHeight);
      lCtx.restore();

      // Problem 2 Fix: Apply depth mask during composite
      if (layer.depthMaskUrl) {
        try {
          const maskImg = await loadImage(layer.depthMaskUrl);
          const maskedCanvas = document.createElement('canvas');
          maskedCanvas.width = finalWidth;
          maskedCanvas.height = finalHeight;
          const mCtx = maskedCanvas.getContext('2d')!;

          mCtx.drawImage(layerTempCanvas, 0, 0);
          mCtx.globalCompositeOperation = 'destination-in';
          mCtx.drawImage(maskImg, 0, 0, finalWidth, finalHeight);
          mCtx.globalCompositeOperation = 'source-over';

          // Use the masked canvas for final draw
          ctx.save();
          ctx.globalAlpha = layer.opacity;
          ctx.translate(layer.x, layer.y);
          ctx.rotate((layer.rotation * Math.PI) / 180);
          ctx.drawImage(maskedCanvas, -finalWidth / 2, -finalHeight / 2);
          ctx.restore();
          continue; // Skip the default draw below
        } catch (e) {
          console.error("Mask application failed, falling back to original layer", e);
        }
      }

      ctx.save();
      ctx.globalAlpha = layer.opacity;
      ctx.translate(layer.x, layer.y);
      ctx.rotate((layer.rotation * Math.PI) / 180);
      ctx.drawImage(layerTempCanvas, -finalWidth / 2, -finalHeight / 2);
      ctx.restore();
    } catch (e) {
      console.warn(`Failed to load layer ${layer.id} for composite`, e);
    }
  }

  return canvas;
};

export const generateMask = async (layers: Layer[], canvasWidth: number, canvasHeight: number): Promise<HTMLCanvasElement> => {
  const canvas = document.createElement('canvas');
  canvas.width = canvasWidth;
  canvas.height = canvasHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Could not get canvas context');

  // White areas = to be generated (empty canvas)
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  const visibleLayers = layers.filter(l => l.visible);

  // Black areas = to be preserved (existing content)
  for (const layer of visibleLayers) {
    try {
      const img = await loadImage(layer.dataUrl);
      ctx.save();
      ctx.translate(layer.x, layer.y);
      ctx.rotate((layer.rotation * Math.PI) / 180);
      const w = layer.width * layer.scale;
      const h = layer.height * layer.scale;

      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = w;
      tempCanvas.height = h;
      const tempCtx = tempCanvas.getContext('2d')!;

      tempCtx.save();
      tempCtx.translate(w/2, h/2);
      tempCtx.scale(layer.flipX ? -1 : 1, layer.flipY ? -1 : 1);
      tempCtx.drawImage(img, -w/2, -h/2, w, h);
      tempCtx.restore();

      const imgData = tempCtx.getImageData(0, 0, w, h);
      const data = imgData.data;
      for (let i = 3; i < data.length; i += 4) {
        if (data[i] > 10) { // arbitrary threshold to handle anti-aliasing slightly
          data[i-3] = 0; // R
          data[i-2] = 0; // G
          data[i-1] = 0; // B
          data[i] = 255; // A
        } else {
          data[i] = 0;   // Make fully transparent
        }
      }
      tempCtx.putImageData(imgData, 0, 0);

      ctx.drawImage(tempCanvas, -w/2, -h/2, w, h);
      ctx.restore();
    } catch (e) {
      console.warn(`Failed to process layer ${layer.id} for mask`, e);
    }
  }
  return canvas;
};

export const getSupportedAspectRatio = (width: number, height: number): '1:1' | '16:9' | '9:16' | '4:3' | '3:4' => {
  const ratio = width / height;
  const options: { label: '1:1' | '16:9' | '9:16' | '4:3' | '3:4', value: number }[] = [
    { label: '1:1', value: 1 },
    { label: '16:9', value: 16 / 9 },
    { label: '9:16', value: 9 / 16 },
    { label: '4:3', value: 4 / 3 },
    { label: '3:4', value: 3 / 4 },
  ];
  return options.reduce((prev, curr) => 
    Math.abs(curr.value - ratio) < Math.abs(prev.value - ratio) ? curr : prev
  ).label;
};

const loadImage = (url: string): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.src = url;
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = reject;
  });
};

import { Flow } from 'flow-sdk';

// Valid image models: "Nano Banana Pro", "Nano Banana 2", "Imagen 4"
const DEFAULT_MODEL = 'Nano Banana 2';

/**
 * Upload a dataUrl to Flow to get a temporary mediaId for AI reference.
 * Note: If Flow.upload is unavailable in a specific environment, 
 * we fallback to Flow.save which is universally supported.
 */
async function uploadToMediaId(dataUrl: string, name: string = 'Reference'): Promise<string> {
  const base64 = dataUrl.split(',')[1];
  const mimeType = dataUrl.split(';')[0].split(':')[1] || 'image/png';

  try {
    // Attempt standard upload
    if (typeof (Flow as any).upload === 'function') {
      const { mediaId } = await (Flow as any).upload({ base64, mimeType, name });
      return mediaId;
    }

    // Fallback to save if upload is not exposed
    const { mediaId } = await Flow.save({ base64, mimeType, name: `Temp_${name}` });
    return mediaId;
  } catch (e) {
    console.error("Media upload/save failed", e);
    throw e;
  }
}

/**
 * Edit an image layer using Flow's image generation.
 */
export async function editImageLayer(
  base64DataUrl: string, 
  prompt: string,
  maskDataUrl?: string | null,
  _editMode?: string,
  aspectRatio?: string,
  options?: { model?: string }
): Promise<string> {
  // Upload the source image to get a mediaId
  const sourceMediaId = await uploadToMediaId(base64DataUrl, 'Source Image');

  const referenceImageMediaIds: string[] = [sourceMediaId];

  if (maskDataUrl) {
    const maskMediaId = await uploadToMediaId(maskDataUrl, 'Mask');
    referenceImageMediaIds.push(maskMediaId);
  }

  // Model selection check - ensure we use valid names
  const modelName = options?.model || DEFAULT_MODEL;

  const result = await Flow.generate.image({
    prompt,
    referenceImageMediaIds,
    modelDisplayName: modelName,
    aspectRatio: (aspectRatio as any) || '1:1',
  });

  return `data:${result.mimeType};base64,${result.base64}`;
}

/**
 * Generate a brand new image from a text prompt.
 */
export async function generateNewImageData(
  prompt: string,
  aspectRatio: string = "1:1",
  options?: { model?: string }
): Promise<string> {
  const modelName = options?.model || DEFAULT_MODEL;

  const result = await Flow.generate.image({
    prompt,
    modelDisplayName: modelName,
    aspectRatio: (aspectRatio as any) || '1:1',
  });

  return `data:${result.mimeType};base64,${result.base64}`;
}

import { TextConfig } from '../types';

export const renderTextToDataUrl = async (config: TextConfig): Promise<{ dataUrl: string; width: number; height: number }> => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  if (!ctx) return { dataUrl: "", width: 100, height: 100 };

  const fontSize = config.fontSize || 48;
  const fontFamily = config.fontFamily || "Inter";
  const fontWeight = config.fontWeight || "normal";
  const fontStyle = config.fontStyle === "italic" ? "italic " : "";

  const fontString = `${fontStyle}${fontWeight} ${fontSize}px "${fontFamily}"`;

  try {
    if (document.fonts) {
      await document.fonts.load(fontString);
    }
  } catch (e) {
    console.warn("Failed to wait for fonts to load", e);
  }

  ctx.font = fontString;
  ctx.fillStyle = config.color || "#ffffff";
  ctx.textAlign = config.textAlign || "left";
  ctx.textBaseline = "top";

  if (config.letterSpacing !== undefined) {
    ctx.letterSpacing = `${config.letterSpacing}px`;
  }

  const lineHeightMult = config.lineHeight || 1.2;
  const lineHeight = fontSize * lineHeightMult;

  // Use regex to avoid string literal issues in some parser environments
  const lines = config.content.split(/\r?\n/);
  let maxWidth = 0;

  for (const line of lines) {
    const measure = ctx.measureText(line);
    if (measure.width > maxWidth) {
      maxWidth = measure.width;
    }
  }

  const width = Math.max(20, maxWidth + 40);
  const paddingY = 20;
  const height = lines.length * lineHeight + paddingY * 2;

  canvas.width = width;
  canvas.height = height;

  // Re-apply styles after resize
  ctx.font = fontString;
  ctx.fillStyle = config.color || "#ffffff";
  ctx.textAlign = config.textAlign || "left";
  ctx.textBaseline = "top";
  if (config.letterSpacing !== undefined) {
    ctx.letterSpacing = `${config.letterSpacing}px`;
  }

  let drawX = config.textAlign === "center" ? width / 2 : config.textAlign === "right" ? width - 20 : 20;

  let currentY = paddingY;
  for (const line of lines) {
    ctx.fillText(line, drawX, currentY);
    currentY += lineHeight;
  }

  return {
    dataUrl: canvas.toDataURL("image/png"),
    width,
    height
  };
};

