    }
  };

  // Problem 2 Fix: Flatten/Commit depth results
  const handleFlattenDepth = async (layerId: string) => {
    const targetLayer = layers.find(l => l.id === layerId);
    if (!targetLayer || !targetLayer.depthEnabled) return;

    setIsProcessing(true);
    setProcessingMessage('Flattening depth composite...');
    setErrorMessage(null);

    try {
      const canvas = await compositeToCanvas(layers, canvasWidth, canvasHeight, 'transparent');
      const finalDataUrl = canvas.toDataURL('image/png');

      commitHistory();

      const flattenedLayer: Layer = {
        id: crypto.randomUUID(),
        type: 'image',
        name: 'Depth Composite',
        dataUrl: finalDataUrl,
        x: canvasWidth / 2,
        y: canvasHeight / 2,
        scale: 1,
        rotation: 0,
        opacity: 1,
        visible: true,
        zIndex: 0,
        width: canvasWidth,
        height: canvasHeight
      };

      setLayers([flattenedLayer]);
      setActiveLayerId(flattenedLayer.id);
    } catch (e) {
      console.error("Flatten failed", e);
      setErrorMessage("Failed to flatten composite");
    } finally {
      setIsProcessing(false);
      setProcessingMessage(null);
    }
  };

  const addLayer = (layer: Omit<Layer, 'id'>) => {
    commitHistory();
    const nextZIndex = layers.length > 0 ? Math.max(...layers.map(l => l.zIndex)) + 1 : 0;
    const newLayer = { ...layer, id: crypto.randomUUID(), zIndex: nextZIndex };
    setLayers(prev => [...prev, newLayer]);
    setActiveLayerId(newLayer.id);
  };

  const toggleVisibility = (id: string) => {
    commitHistory();
    setLayers(prev => prev.map(l => l.id === id ? { ...l, visible: !l.visible } : l));
  };

  const deleteLayer = (id: string) => {
    commitHistory();
    setLayers(prev => prev.filter(l => l.id !== id));
    if (activeLayerId === id) setActiveLayerId(null);
  };

  const moveLayer = (id: string, direction: 'up' | 'down') => {
    commitHistory();
    setLayers(prev => {
      const sorted = [...prev].sort((a, b) => a.zIndex - b.zIndex);
      const currIdx = sorted.findIndex(l => l.id === id);
      if (currIdx < 0) return prev;

      if (direction === 'up' && currIdx === sorted.length - 1) return prev;
      if (direction === 'down' && currIdx === 0) return prev;

      const targetIdx = direction === 'up' ? currIdx + 1 : currIdx - 1;

      const newSorted = [...sorted];
      const tempZ = newSorted[currIdx].zIndex;
      newSorted[currIdx] = { ...newSorted[currIdx], zIndex: newSorted[targetIdx].zIndex, depthEnabled: false };
      newSorted[targetIdx] = { ...newSorted[targetIdx], zIndex: tempZ, depthEnabled: false };

      return newSorted;
    });
  };

  const duplicateLayer = (id: string) => {
    const layer = layers.find(l => l.id === id);
    if (!layer) return;
    addLayer({
      ...layer,
      name: `${layer.name} copy`,
      x: layer.x + 20,
      y: layer.y + 20,
      zIndex: Math.max(0, ...layers.map(l => l.zIndex)) + 1
    });
  };

  const handleAddText = async () => {
    const textConfig = {
      content: 'New Text',
      fontSize: 80,
      fontFamily: 'Google Sans',
      color: '#ffffff',
      fontWeight: 'bold',
      textAlign: 'center' as const
    };

    const { dataUrl, width, height } = await renderTextToDataUrl(textConfig);

    addLayer({
      type: 'text',
      name: 'Text Layer',
      dataUrl,
      x: canvasWidth / 2,
      y: canvasHeight / 2,
      width,
      height,
      scale: 1,
      rotation: 0,
      opacity: 1,
      visible: true,
      zIndex: layers.length,
      textConfig
    });
  };

  const handleAddImageGallery = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (!media) return;
      const dataUrl = `data:${media.mimeType};base64,${media.base64}`;
      const img = new Image();
      img.onload = () => {
        addLayer({
          type: 'image',
          name: media.name || 'Gallery Image',
          dataUrl,
          width: img.width,
          height: img.height,
          scale: Math.min(1, canvasWidth / img.width, canvasHeight / img.height) * 0.8,
          x: canvasWidth / 2,
          y: canvasHeight / 2,
          rotation: 0,
          opacity: 1,
          visible: true,
          zIndex: layers.length
        });
      };
      img.src = dataUrl;
    } catch (error) {
      console.error('Failed to select media', error);
    }
  };

  const handleWebcamCapture = (dataUrl: string) => {
    setIsWebcamOpen(false);
    const img = new Image();
    img.onload = () => {
      addLayer({
        type: 'image',
        name: 'Webcam Capture',
        dataUrl,
        width: img.width,
        height: img.height,
        scale: Math.min(1, canvasWidth / img.width, canvasHeight / img.height) * 0.8,
        x: canvasWidth / 2,
        y: canvasHeight / 2,
        rotation: 0,
        opacity: 1,
        visible: true,
        zIndex: layers.length
      });
    };
    img.src = dataUrl;
  };

  const handleApplyCrop = useCallback(async () => {
    const activeLayer = layers.find(l => l.id === activeLayerId);
    if (!activeLayer) return;

    setIsProcessing(true);
    setErrorMessage(null);
    try {
      const img = new Image();
      img.src = activeLayer.dataUrl;
      img.crossOrigin = "anonymous";
      await new Promise((resolve, reject) => { img.onload = resolve; img.onerror = reject; });

      const canvas = document.createElement('canvas');
      const sw = activeLayer.width * cropRect.width;
      const sh = activeLayer.height * cropRect.height;
      canvas.width = sw;
      canvas.height = sh;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error("Could not get context");

      ctx.drawImage(img, cropRect.x * activeLayer.width, cropRect.y * activeLayer.height, sw, sh, 0, 0, sw, sh);
      const newDataUrl = canvas.toDataURL('image/png');
      commitHistory();

      const rad = (activeLayer.rotation * Math.PI) / 180;
      const localOffX = (cropRect.x + cropRect.width / 2 - 0.5) * activeLayer.width * activeLayer.scale;
      const localOffY = (cropRect.y + cropRect.height / 2 - 0.5) * activeLayer.height * activeLayer.scale;
      const worldDx = localOffX * Math.cos(rad) - localOffY * Math.sin(rad);
      const worldDy = localOffX * Math.sin(rad) + localOffY * Math.cos(rad);

      updateLayer(activeLayer.id, {
        dataUrl: newDataUrl, width: sw, height: sh, x: activeLayer.x + worldDx, y: activeLayer.y + worldDy
      });
      setIsCropping(false);
    } catch (e) {
      console.error(e);
      setErrorMessage('Cropping failed');
    } finally {
      setIsProcessing(false);
    }
  }, [layers, activeLayerId, cropRect, commitHistory]);

  const handleUndo = () => {
    const prev = undo({ layers, canvasWidth, canvasHeight });
    if (prev) {
      setLayers(prev.layers);
      setCanvasWidth(prev.canvasWidth);
      setCanvasHeight(prev.canvasHeight);
    }
  };

  const handleRedo = () => {
    const next = redo({ layers, canvasWidth, canvasHeight });
    if (next) {
      setLayers(next.layers);
      setCanvasWidth(next.canvasWidth);
      setCanvasHeight(next.canvasHeight);
    }
  };

  const handleSaveToGallery = async () => {
    setIsProcessing(true);
    setErrorMessage(null);
    try {
      const canvas = await compositeToCanvas(layers, canvasWidth, canvasHeight);
      const base64 = canvas.toDataURL('image/png').split(',')[1];

      await Flow.save({
        base64,
        mimeType: 'image/png',
        name: 'Composition'
      });
    } catch (e) {
      console.error("Gallery save failed", e);
      setErrorMessage('Gallery save failed');
    } finally {
      setIsProcessing(false);
    }
  };

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (
        document.activeElement instanceof HTMLInputElement || 
        document.activeElement instanceof HTMLTextAreaElement
      ) {
        return;
      }

      if (e.key === 'Enter') {
        if (isCropping) { e.preventDefault(); handleApplyCrop(); }
      } else if (e.key === 'Escape') {
        if (isCropping) setIsCropping(false);
        setErrorMessage(null);
      } else if (e.key === 'Backspace' || e.key === 'Delete') {
        if (activeLayerId && !isProcessing && !isInpainting && !isOutpainting && !isCropping && !promptMode) {
          e.preventDefault();
          commitHistory();
          setLayers(prev => prev.filter(l => l.id !== activeLayerId));
          setActiveLayerId(null);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isCropping, handleApplyCrop, activeLayerId, isProcessing, isInpainting, isOutpainting, promptMode, commitHistory]);

  return (
    <div className="flex h-screen w-full bg-zinc-950 font-sans text-white overflow-hidden">
      <LayerSidebar 
        layers={layers}
        activeLayerId={activeLayerId}
        onSelectLayer={setActiveLayerId}
        onToggleVisibility={toggleVisibility}
        onDeleteLayer={deleteLayer}
        onMoveLayer={moveLayer}
        onDuplicateLayer={duplicateLayer}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        onAddText={handleAddText}
        onAddImageGallery={handleAddImageGallery}
        onAddImageCamera={() => setIsWebcamOpen(true)}
        isProcessing={isProcessing}
      />

      <div className="flex-1 relative flex flex-col min-w-0">
        {errorMessage && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000] flex items-center gap-3 px-4 py-3 bg-red-500/90 backdrop-blur-xl border border-red-400/50 rounded-2xl shadow-2xl text-white animate-in slide-in-from-top-4 duration-300">
            <AlertCircle size={18} />
            <span className="text-[12px] font-bold tracking-wide uppercase">{errorMessage}</span>
            <button onClick={() => setErrorMessage(null)} className="ml-2 p-1 hover:bg-white/10 rounded-full transition-colors">
              <X size={14} />
            </button>
          </div>
        )}

        <EditorCanvas
          layers={layers}
          activeLayerId={activeLayerId}
          onSelectLayer={setActiveLayerId}
          onUpdateLayer={updateLayer}
          canvasWidth={canvasWidth}
          canvasHeight={canvasHeight}
          isCropping={isCropping}
          isInpainting={isInpainting}
          isOutpainting={isOutpainting}
          isProcessing={isProcessing}
          cropRect={cropRect}
          onUpdateCrop={setCropRect}
          onCommitHistory={commitHistory}
          onInpaintRequest={() => {
            setPromptMode('inpaint');
          }}
          onUpdateMask={(url) => {
            setMaskDataUrl(url);
            if (isInpainting && !promptMode) {
              setPromptMode('inpaint');
            }
          }}
        />

        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[100] flex flex-col items-center gap-2">
          <PromptBar 
            isActive={!!promptMode && !isProcessing} 
            mode={promptMode || 'refine'} 
            defaultPrompt={promptMode === 'refine' ? "Harmonize the scene, unifying the lighting and colors." : ""}
            onClose={() => { 
                setPromptMode(null); 
                setIsInpainting(false); 
                setIsOutpainting(false); 
                setMaskDataUrl(null);
            }} 
            onConfirm={handlePromptConfirm} 
            isProcessing={isProcessing} 
          />
          <Toolbar
            isProcessing={isProcessing}
            processingMessage={processingMessage}
            processingProgress={processingProgress}
            isOutpainting={isOutpainting}
            isCropping={isCropping}
            isInpainting={isInpainting}
            promptMode={promptMode}
            canUndo={canUndo}
            canRedo={canRedo}
            onUndo={handleUndo}
            onRedo={handleRedo}
            onRefine={() => {
              if (promptMode === 'refine') {
                setPromptMode(null);
              } else {
                setPromptMode('refine');
              }
            }}
            onOutpaint={() => {
              if (isOutpainting) {
                setIsOutpainting(false);
                setPromptMode(null);
              } else {
                setIsOutpainting(true);
                setPromptMode('outpaint');
              }
            }}
            onInpaint={() => {
              if (isInpainting) {
                setIsInpainting(false);
                setMaskDataUrl(null);
                setPromptMode(null);
              } else {
                setIsInpainting(true);
              }
            }}
            onStartCrop={() => { setCropRect({ x: 0, y: 0, width: 1, height: 1 }); setIsCropping(true); }}
            onApplyCrop={handleApplyCrop}
            onCancelCrop={() => {
              setIsCropping(false);
              setIsInpainting(false);
              setIsOutpainting(false);
              setPromptMode(null);
            }}
            onRemoveBackground={() => {
              const activeLayer = layers.find(l => l.id === activeLayerId);
              if (activeLayer) {
                setProcessingMessage('Preparing background remover...');
                setProcessingProgress(0);
                setIsProcessing(true);
                setErrorMessage(null);

                setTimeout(async () => {
                  try {
                    const bg = await removeBackground(activeLayer.dataUrl, bgModel, (p) => {
                      if (p.status === 'init') {
                        setProcessingMessage('Initializing AI...');
                      } else if (p.status === 'downloading') {
                        setProcessingMessage('Downloading model...');
                        if (p.progress !== undefined) setProcessingProgress(Math.round(p.progress));
                      } else if (p.status === 'done' || p.status === 'processing') {
                        setProcessingMessage('Removing background...');
                        setProcessingProgress(0);
                      }
                    });
                    commitHistory();
                    updateLayer(activeLayer.id, { dataUrl: bg });
                  } catch (e) {
                    console.error(e);
                    setErrorMessage('Background removal failed');
                  } finally {
                    setIsProcessing(false);
                    setProcessingMessage(null);
                    setProcessingProgress(0);
                  }
                }, 100);
              }
            }}
          />
        </div>
      </div>

      <PropertiesSidebar
        layer={layers.find(l => l.id === activeLayerId) || null}
        isTopmostLayer={layers.length > 0 && activeLayerId === [...layers].sort((a,b) => b.zIndex - a.zIndex)[0]?.id}
        onUpdateLayer={updateLayer}
        canvasWidth={canvasWidth}
        canvasHeight={canvasHeight}
        onUpdateCanvas={(w, h) => { setCanvasWidth(w); setCanvasHeight(h); }}
        onResetCanvas={() => { setCanvasWidth(DEFAULT_CANVAS_WIDTH); setCanvasHeight(DEFAULT_CANVAS_HEIGHT); }}
        isAspectRatioLocked={false}
        onToggleAspectRatioLock={() => {}}
        onCommitHistory={commitHistory}
        onSaveToGallery={handleSaveToGallery}
        onFlattenDepth={handleFlattenDepth}
        isProcessing={isProcessing}
        aiModel={aiModel}
        onAiModelChange={setAiModel}
        bgModel={bgModel}
        onBgModelChange={setBgModel}
        onToggleDepthSort={handleToggleDepthSort}
      />

      <WebcamModal 
        isOpen={isWebcamOpen} 
        onClose={() => setIsWebcamOpen(false)} 
        onCapture={handleWebcamCapture} 
      />
    </div>
  );
}
